from pwn import *
context.log_level='error'
# offsets of read/write/strlen in local libc
libc=ELF('/lib/x86_64-linux-gnu/libc.so.6')
for s in ['read','write','strlen','strtol','open','preopen' ]:
    try:
        print(s, hex(libc.symbols[s]))
    except Exception as e:
        print(s,'ERR',e)
print('pop rdx ; ret', hex(next(libc.search(asm('pop rdx; ret')))))
